-- Won Nyaci Run 2026 MySQL starter database
-- Generated from the supplied run/payment references. Verify banking/payment details with the organisers before live use.
CREATE DATABASE IF NOT EXISTS won_nyaci_run CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE won_nyaci_run;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,is_admin TINYINT(1) NOT NULL DEFAULT 0,remember_token VARCHAR(100) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,excerpt TEXT NULL,body LONGTEXT NOT NULL,image VARCHAR(255) NULL,published_at TIMESTAMP NULL,is_published TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE contact_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(50) NULL,subject VARCHAR(190) NULL,message TEXT NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE payment_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,method VARCHAR(255) NOT NULL,label VARCHAR(190) NOT NULL,details JSON NOT NULL,sort_order INT UNSIGNED NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE site_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`key` VARCHAR(255) NOT NULL UNIQUE,value TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE x_posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tweet_id VARCHAR(255) NOT NULL UNIQUE,text TEXT NOT NULL,url TEXT NOT NULL,author_username VARCHAR(255) NULL,media JSON NULL,published_at TIMESTAMP NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE cache (`key` VARCHAR(255) PRIMARY KEY,value MEDIUMTEXT NOT NULL,expiration INT NOT NULL) ENGINE=InnoDB;
CREATE TABLE sessions (id VARCHAR(255) PRIMARY KEY,user_id BIGINT UNSIGNED NULL,ip_address VARCHAR(45) NULL,user_agent TEXT NULL,payload TEXT NOT NULL,last_activity INT NOT NULL,INDEX(last_activity),INDEX(user_id)) ENGINE=InnoDB;
