INSERT INTO posts (title,slug,excerpt,body,image,published_at,is_published,created_at,updated_at) VALUES ('Welcome to Won Nyaci Run 2026','welcome-to-won-nyaci-run-2026','Running for our culture, our health and our future.','On 24 October 2026, Lango comes together at Old Akii Bua Stadium for a day of movement, culture and practical community impact. Every kit contributes to a collective effort supporting free wheelchairs and crutches for people living with disabilities in Lango. Registration and aerobics begin at 6:00 AM, with running at 7:30 AM.','images/run-flyer-social.png','2026-09-14 07:00:00',1,NOW(),NOW());
